    { id: "s28", author: "Ackerson", year: 2019, journal: "Clin Infect Dis", title: "Severe Morbidity and Mortality Associated With Respiratory Syncytial Virus Versus Influenza Infection in Hospitalized Older Adults", doi: "10.1093/cid/ciy991", url: "https://europepmc.org/article/MED/30452608", design: "Retrospective database", region: "US", country: "United States (CA)", age: "≥60", n: "645 RSV admissions", setting: "Inpatient", grade: "B", gradeWhy: "Integrated health system cohort; comparative outcomes; outside geography" },
    { id: "s29", author: "Choi", year: 2022, journal: "Influenza Other Respir Viruses", title: "Cost determinants among adults hospitalized with respiratory syncytial virus in the United States, 2017-2019", doi: "10.1111/irv.12912", url: "https://europepmc.org/article/MED/34605182", design: "Prospective cohort", region: "US", country: "United States (NY)", age: "≥18", n: "601 admissions with cost data", setting: "Inpatient", grade: "B", gradeWhy: "Prospective cost data; all adults; outside geography" },
    { id: "s30", author: "Carrico", year: 2024, journal: "J Infect Dis", title: "The Annual Economic Burden of Respiratory Syncytial Virus in Adults in the United States", doi: "10.1093/infdis/jiad559", url: "https://europepmc.org/article/MED/38060972", design: "Model-based estimate", region: "US", country: "United States", age: "≥60", n: "Cost-of-illness model", setting: "Mixed", grade: "B", gradeWhy: "Model with wide uncertainty interval; outside geography" },
    { id: "s31", author: "Osei-Yeboah", year: 2024, journal: "Influenza Other Respir Viruses", title: "Burden of Respiratory Syncytial Virus (RSV) Infection Among Adults in Nursing and Care Homes: A Systematic Review", doi: "10.1111/irv.70008", url: "https://europepmc.org/article/MED/39284784", design: "Systematic review", region: "Global", country: "High-income settings", age: "Care-home residents", n: "20 studies", setting: "Mixed", grade: "B", gradeWhy: "Range across heterogeneous care-home outbreak studies, no pooled estimate" },
    /* ---- Excluded at full text (verified references) ---- */
    { id: "x01", author: "Nguyen-Van-Tam", year: 2022, journal: "Eur Respir Rev", title: "Burden of respiratory syncytial virus infection in older and high-risk adults: a systematic review and meta-analysis of the evidence from developed countries", doi: "10.1183/16000617.0105-2022", url: "https://europepmc.org/article/MED/36384703", design: "Meta-analysis", region: "Global", country: "Developed countries", age: "≥60", n: "103 articles", setting: "Mixed", excluded: "Review without new data", exclWhy: "Reports RSV as a share of symptomatic infections only; the abstract states population incidence could not be estimated" },
    { id: "x02", author: "Rozenbaum", year: 2023, journal: "Infect Dis Ther", title: "Incidence of Respiratory Syncytial Virus Infection in Older Adults: Limitations of Current Data", doi: "10.1007/s40121-023-00802-4", url: "https://europepmc.org/article/MED/37310617", design: "Systematic review", region: "Global", country: "High-income Western countries", age: "Older adults", n: "71 studies", setting: "Mixed", excluded: "Review without new data", exclWhy: "Narrative synthesis of study limitations; no pooled estimate" },
    { id: "x03", author: "Kenmoe", year: 2024, journal: "Curr Opin Infect Dis", title: "The disease burden of respiratory syncytial virus in older adults", doi: "10.1097/QCO.0000000000001000", url: "https://europepmc.org/article/MED/38197402", design: "Narrative review", region: "Global", country: "Industrialised countries", age: "≥60", n: "—", setting: "Mixed", excluded: "Review without new data", exclWhy: "Figures cited are secondary, taken from other included sources" },
    { id: "x04", author: "Maggi", year: 2022, journal: "Vaccines", title: "Rate of Hospitalizations and Mortality of Respiratory Syncytial Virus Infection Compared to Influenza in Older People: A Systematic Review and Meta-Analysis", doi: "10.3390/vaccines10122092", url: "https://europepmc.org/article/MED/36560501", design: "Meta-analysis", region: "Global", country: "Global", age: "Older people", n: "16 studies", setting: "Mixed", excluded: "No quantitative outcome", exclWhy: "Comparative RSV-versus-influenza ratios only; no absolute rate in the abstract" },
    { id: "x05", author: "Osei-Yeboah", year: 2024, journal: "J Infect Dis", title: "Respiratory Syncytial Virus-Associated Hospitalization in Adults With Comorbidities in 2 European Countries: A Modeling Study", doi: "10.1093/infdis/jiad510", url: "https://europepmc.org/article/MED/37970679", design: "Model-based estimate", region: "Europe", country: "Denmark, Scotland", age: "≥45 with comorbidities", n: "National data, 2010–2018", setting: "Inpatient", excluded: "Wrong population", exclWhy: "Rates are per 1,000 comorbid adults ≥45, not an older-adult population rate" },
    { id: "x06", author: "Cai", year: 2020, journal: "Influenza Other Respir Viruses", title: "Risk factors for hospitalized respiratory syncytial virus disease and its severe outcomes", doi: "10.1111/irv.12729", url: "https://europepmc.org/article/MED/32064773", design: "Retrospective database", region: "Europe", country: "Germany", age: "All ages (97% < 5 y)", n: "8,761 RSV diagnoses", setting: "Inpatient", excluded: "Wrong population", exclWhy: "8,521 of 8,761 RSV cases are children under five; results are paediatric risk factors" },
    { id: "x07", author: "Weinert", year: 2025, journal: "Infect Dis Ther", title: "Respiratory Syncytial Virus (RSV) as a Secondary Diagnosis among Hospitalized Patients in Germany: Outcomes and Economic Burden", doi: "10.1007/s40121-025-01152-z", url: "https://europepmc.org/article/MED/40279020", design: "Retrospective database", region: "Europe", country: "Germany", age: "≥18, no older-adult stratum", n: "6 M insured", setting: "Inpatient", excluded: "Wrong population", exclWhy: "Outcomes reported as ratios versus controls for all adults; no ≥60 stratum" },
    { id: "x08", author: "Falsey", year: 2005, journal: "N Engl J Med", title: "Respiratory syncytial virus infection in elderly and high-risk adults", doi: "10.1056/NEJMoa043951", url: "https://europepmc.org/article/MED/15858184", design: "Prospective cohort", region: "US", country: "United States", age: "≥65", n: "608 healthy elderly", setting: "Mixed", excluded: "Data period before 2015", exclWhy: "Landmark study, but published 2005 and outside the geography" },
    { id: "x09", author: "Widmer", year: 2012, journal: "J Infect Dis", title: "Rates of hospitalizations for respiratory syncytial virus, human metapneumovirus, and influenza virus in older adults", doi: "10.1093/infdis/jis309", url: "https://europepmc.org/article/MED/22529314", design: "Surveillance", region: "US", country: "United States (TN)", age: "≥50", n: "508 tested", setting: "Inpatient", excluded: "Data period before 2015", exclWhy: "Published 2012; population ≥50; outside the geography" }
